INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT159-S1-Q25$batch12$, 159, 1, 25, $batch12$Parallel Flaw$batch12$, $batch12$Artist: I have never won a prize at the Art Competition, even though several of my submitted paintings have received widespread recognition and have sold thousands of copies as posters. I know six other popular artists who have submitted works to that competition and fared no better. Thus, winning the Art Competition proves that an artist is no good.$batch12$, $batch12$The pattern of flawed reasoning in which one of the following arguments most closely resembles that in the artist’s argument?$batch12$, $batch12$D$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$Researcher: I have never won a prize at the Science Competition, although I have obtained patents for several of my inventions and they have been extremely lucrative. Other scientists have had similar experiences. Therefore, the judges are using some criterion other than marketability to judge the inventions.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Cook: I always win a prize at the Cooking Competition, even though my entries are regarded by the general public as unusual and unappealing. Other cooks have reported similar experiences. Thus, winning proves that one’s culinary creation is not to most people’s taste.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Professor: The same essays that have won nothing in some years at the Philosophical Essay Competition have won the grand prize in other years. So the essays are not judged entirely on quality.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$Student: The student government never takes my proposals seriously, even when these proposals have the support of most students. Others have also introduced widely supported proposals, but the student government has not seriously considered theirs either. So the student government takes only bad proposals seriously.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$Travel agent: When I do my most creative and dedicated work, the airlines reduce my commissions. And when I do rushed work, they send me fruit baskets in gratitude. I conclude that airlines want to discourage good ideas and hard work.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Winning the Art Competition proves an artist is no good.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The artist and six other popular artists never won, despite popular success.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The competition hasn't rewarded these popular artists. The argument jumps to the claim that winners must be bad. Not rewarding some good work doesn't mean everything rewarded is bad.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Popular work isn't rewarded, so whatever gets rewarded is bad.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This concludes the judges use some other criterion, a reasonable inference.$batch12$), ($batch12$B$batch12$, $batch12$This cook always wins. The original is about popular work that never wins.$batch12$), ($batch12$C$batch12$, $batch12$This concludes essays aren't judged only on quality, which is fair given the inconsistency.$batch12$), ($batch12$D$batch12$, $batch12$The student government never seriously considers popular proposals, so the argument concludes it takes only bad proposals seriously. Same jump.$batch12$), ($batch12$E$batch12$, $batch12$This links good work to reduced pay and rushed work to rewards. A different pattern.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT159-S1-Q25$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
